program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for rows in combinations(options, k):
        ids = [row['id'] for row in rows]
        if valid(ids):
            result = ids
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if not valid(current):
        status('report')
else:
    if valid(result):
        write('/output/selection', result)
        current = result
    else:
        current = []
if current and valid(current):
    delivery = receipt('report')
    if delivery == 'success':
        pass
    elif delivery == 'failure':
        status('report')
    elif delivery == 'unknown':
        status('report')
    elif delivery == 'unattempted':
        state = status('report')
        if state == 'not_sent':
            send('report', 'team', current)
        else:
            pass
if exists('/tmp/cache'):
    delete('/tmp/cache')

